// Script: inject weeks 4, 5, 6 questions into extraQuestions.json
const fs = require('fs');
const path = require('path');

const filePath = path.join(__dirname, '../src/data/extraQuestions.json');
const existing = JSON.parse(fs.readFileSync(filePath, 'utf8'));

const week4 = [
  {id:"week4_gen_0",text:"What does TVET stand for in the context of sustainable development education?",options:[{letter:"A",text:"Technical and Vocational Education and Training"},{letter:"B",text:"Technology and Vocational Employment Training"},{letter:"C",text:"Trade and Vocational Education Testing"},{letter:"D",text:"Technical and Vocational Evaluation Training"}],answer:"A",feedback:"TVET stands for Technical and Vocational Education and Training — a pathway that equips learners with practical skills for the world of work."},
  {id:"week4_gen_1",text:"Which of the following best describes 'greening TVET'?",options:[{letter:"A",text:"Painting TVET institutions with green colours to signal eco-friendliness"},{letter:"B",text:"Integrating sustainability principles, green skills and environmental awareness into TVET curricula and operations"},{letter:"C",text:"Replacing all TVET programmes with environmental science degrees"},{letter:"D",text:"Reducing the number of TVET graduates to protect natural resources"}],answer:"B",feedback:"Greening TVET means embedding sustainability across content, pedagogy, campus operations and governance so graduates can contribute to a green economy."},
  {id:"week4_gen_2",text:"Green skills are MOST accurately described as:",options:[{letter:"A",text:"Knowledge and abilities needed only in renewable energy sectors"},{letter:"B",text:"Technical competencies required to operate recycling plants"},{letter:"C",text:"The knowledge, abilities, values and attitudes needed to live and work in a sustainable and resource-efficient society"},{letter:"D",text:"IT skills used to measure carbon footprints digitally"}],answer:"C",feedback:"Green skills are broadly defined as knowledge, abilities, values and attitudes that support sustainable development across all sectors of the economy."},
  {id:"week4_gen_3",text:"The 'green economy' is characterised by:",options:[{letter:"A",text:"An economy that exclusively relies on solar and wind energy"},{letter:"B",text:"Economic growth that results in reduced environmental risks, ecological scarcity and improved human well-being and social equity"},{letter:"C",text:"An economy where only government-owned enterprises operate"},{letter:"D",text:"Zero industrial production to prevent pollution"}],answer:"B",feedback:"UNEP defines a green economy as one that results in improved human well-being and social equity while significantly reducing environmental risks and ecological scarcities."},
  {id:"week4_gen_4",text:"In a circular economy, waste from one process ideally becomes:",options:[{letter:"A",text:"Landfill material that is safely buried"},{letter:"B",text:"A raw material or resource input for another process"},{letter:"C",text:"An export commodity sold to developing nations"},{letter:"D",text:"A source of renewable energy through incineration only"}],answer:"B",feedback:"The circular economy model keeps materials in use as long as possible; waste outputs are designed to be inputs for other processes, closing resource loops."},
  {id:"week4_gen_5",text:"Which SDG is most directly linked to decent work and economic growth?",options:[{letter:"A",text:"SDG 3"},{letter:"B",text:"SDG 6"},{letter:"C",text:"SDG 8"},{letter:"D",text:"SDG 11"}],answer:"C",feedback:"SDG 8 is 'Decent Work and Economic Growth,' targeting full employment, decent work for all and sustained, inclusive economic growth."},
  {id:"week4_gen_6",text:"SDG 9 focuses on:",options:[{letter:"A",text:"Zero Hunger"},{letter:"B",text:"Industry, Innovation and Infrastructure"},{letter:"C",text:"Life on Land"},{letter:"D",text:"Climate Action"}],answer:"B",feedback:"SDG 9 — Industry, Innovation and Infrastructure — promotes resilient infrastructure, inclusive industrialisation and innovation."},
  {id:"week4_gen_7",text:"Which of the following is an example of a 'green job'?",options:[{letter:"A",text:"A corporate lawyer specialising in fossil fuel mergers"},{letter:"B",text:"A solar panel installer who reduces dependence on coal power"},{letter:"C",text:"A fast-fashion retail manager optimising clothing turnover"},{letter:"D",text:"A petroleum extraction engineer"}],answer:"B",feedback:"Green jobs are positions in economic activities that produce environmental goods or services, such as solar installation, which contributes to reducing carbon emissions."},
  {id:"week4_gen_8",text:"Eco-innovation refers to:",options:[{letter:"A",text:"Innovations that only occur in ecological research laboratories"},{letter:"B",text:"Any form of innovation resulting in or aiming at progress towards sustainable development by reducing impacts on the environment"},{letter:"C",text:"Replacing all innovation with traditional indigenous practices"},{letter:"D",text:"Innovations that increase resource consumption for economic growth"}],answer:"B",feedback:"Eco-innovation encompasses innovations — in products, processes, services, or social structures — that reduce environmental burdens while creating economic and social value."},
  {id:"week4_gen_9",text:"Sustainable entrepreneurship differs from conventional entrepreneurship primarily because it:",options:[{letter:"A",text:"Focuses only on non-profit ventures"},{letter:"B",text:"Requires government grants to operate"},{letter:"C",text:"Creates economic value while simultaneously generating positive social and environmental outcomes"},{letter:"D",text:"Avoids using technology in business operations"}],answer:"C",feedback:"Sustainable entrepreneurs seek to address social and environmental problems through market-based solutions, balancing profit with purpose."},
  {id:"week4_gen_10",text:"A social enterprise is best characterised as:",options:[{letter:"A",text:"A government department responsible for social welfare"},{letter:"B",text:"A charity that accepts only non-cash donations"},{letter:"C",text:"A business whose primary objective is social, environmental or community benefit, with surpluses reinvested towards that mission"},{letter:"D",text:"A corporation that donates 5% of profits to charity"}],answer:"C",feedback:"Social enterprises are organisations that trade commercially but are driven primarily by a social or environmental mission; profits are reinvested rather than maximised for shareholders."},
  {id:"week4_gen_11",text:"The principle of 'cradle-to-cradle' design in the circular economy means:",options:[{letter:"A",text:"Products are designed for landfill disposal at the end of their life"},{letter:"B",text:"Every material in a product is designed to be safely recovered and re-used perpetually"},{letter:"C",text:"Products are manufactured from birth to death without recycling"},{letter:"D",text:"Only biological materials may be used in manufacturing"}],answer:"B",feedback:"Cradle-to-cradle design, developed by McDonough and Braungart, ensures all materials cycle continuously as either biological or technical nutrients, eliminating the concept of waste."},
  {id:"week4_gen_12",text:"Which UNESCO initiative specifically supports the greening of TVET at the global level?",options:[{letter:"A",text:"UNESCO's Man and the Biosphere Programme"},{letter:"B",text:"UNESCO-UNEVOC's work on greening TVET and developing green skills frameworks"},{letter:"C",text:"UNESCO's World Heritage Convention"},{letter:"D",text:"UNESCO's International Hydrological Programme"}],answer:"B",feedback:"UNESCO-UNEVOC is the dedicated UNESCO centre for TVET and has led global frameworks and networks to integrate green skills and sustainability into TVET systems."},
  {id:"week4_gen_13",text:"Which of the following is NOT typically considered a dimension of the green economy transition?",options:[{letter:"A",text:"Decoupling economic growth from resource use"},{letter:"B",text:"Increasing GDP by accelerating fossil fuel extraction"},{letter:"C",text:"Investing in renewable energy and energy efficiency"},{letter:"D",text:"Promoting resource-efficient production and consumption"}],answer:"B",feedback:"The green economy explicitly aims to decouple growth from environmental harm; accelerating fossil fuel extraction undermines rather than supports this transition."},
  {id:"week4_gen_14",text:"In the context of TVET and the labour market, 'skills mismatch' in the green transition refers to:",options:[{letter:"A",text:"Workers having too many qualifications"},{letter:"B",text:"A gap between the green competencies employers need and those the workforce currently possesses"},{letter:"C",text:"Disagreements between employers and employees over wages"},{letter:"D",text:"Workers refusing to relocate to rural areas for green jobs"}],answer:"B",feedback:"Skills mismatch in the green transition means current workers lack the specific competencies — technical, social or managerial — required by a low-carbon, resource-efficient economy."},
  {id:"week4_gen_15",text:"Which concept describes replacing a linear 'take-make-dispose' model with one that regenerates natural systems?",options:[{letter:"A",text:"Just-in-time manufacturing"},{letter:"B",text:"Circular economy"},{letter:"C",text:"Globalisation"},{letter:"D",text:"Import substitution"}],answer:"B",feedback:"The circular economy explicitly rejects the linear take-make-dispose approach, instead designing products and systems that regenerate natural capital and eliminate waste."},
  {id:"week4_gen_16",text:"The ILO's 'just transition' framework for green jobs emphasises:",options:[{letter:"A",text:"Rapid closure of all fossil fuel industries without support for workers"},{letter:"B",text:"Ensuring that the shift to a greener economy is fair and inclusive, protecting workers and communities dependent on carbon-intensive industries"},{letter:"C",text:"Prioritising economic growth over environmental protection"},{letter:"D",text:"Outsourcing all green manufacturing to low-income countries"}],answer:"B",feedback:"The ILO's just transition framework calls for social dialogue, skills development and social protection so that workers and communities can benefit from and not be harmed by the green economy shift."},
  {id:"week4_gen_17",text:"Eco-innovation can take place at which of the following levels? (Select the most comprehensive answer)",options:[{letter:"A",text:"Only at the product level"},{letter:"B",text:"Only at the process level"},{letter:"C",text:"Product, process, marketing, organisational and system levels"},{letter:"D",text:"Only at the national policy level"}],answer:"C",feedback:"Eco-innovation occurs across multiple levels: in products, production processes, marketing methods, organisational practices and broader socio-technical systems."},
  {id:"week4_gen_18",text:"Which of the following best exemplifies a 'social enterprise' model in education?",options:[{letter:"A",text:"A for-profit university maximising shareholder returns"},{letter:"B",text:"A TVET college that trains unemployed youth in solar installation and uses fee income to subsidise training for disadvantaged students"},{letter:"C",text:"A government ministry that sets national education policy"},{letter:"D",text:"A private tutoring business offering exam preparation for profit"}],answer:"B",feedback:"A TVET college cross-subsidising disadvantaged learners through earned revenue while pursuing a social mission (skills for employment) is a classic social enterprise model."},
  {id:"week4_gen_19",text:"Which term describes the process by which traditional industries adapt their operations and workforce to become more environmentally sustainable?",options:[{letter:"A",text:"Offshoring"},{letter:"B",text:"Greening of existing industries"},{letter:"C",text:"Privatisation"},{letter:"D",text:"Financialisation"}],answer:"B",feedback:"Greening of existing industries refers to retrofitting operations, processes and workforce skills in conventional sectors to reduce environmental impact and improve sustainability."},
  {id:"week4_gen_20",text:"SDG 8 calls for achieving full and productive employment and decent work for all by which year?",options:[{letter:"A",text:"2020"},{letter:"B",text:"2025"},{letter:"C",text:"2030"},{letter:"D",text:"2050"}],answer:"C",feedback:"SDG 8, like all SDGs, has a 2030 target horizon; it specifically calls for full and productive employment and decent work for all women and men by 2030."},
  {id:"week4_gen_21",text:"Which of the following is an indicator used under SDG 9 to track progress on inclusive industrialisation?",options:[{letter:"A",text:"Percentage of population with access to clean water"},{letter:"B",text:"Manufacturing value added as a proportion of GDP"},{letter:"C",text:"Under-5 mortality rate"},{letter:"D",text:"Forest cover percentage"}],answer:"B",feedback:"Manufacturing value added as a share of GDP and per capita is a key SDG 9 indicator reflecting the degree of industrialisation within a country."},
  {id:"week4_gen_22",text:"The concept of 'extended producer responsibility' (EPR) is most aligned with which economy model?",options:[{letter:"A",text:"Linear economy"},{letter:"B",text:"Circular economy"},{letter:"C",text:"Subsistence economy"},{letter:"D",text:"Command economy"}],answer:"B",feedback:"EPR, which makes producers responsible for the end-of-life management of their products, is a key policy instrument supporting circular economy goals."},
  {id:"week4_gen_23",text:"In TVET, 'green curricula' should ideally include:",options:[{letter:"A",text:"Only theoretical environmental science modules"},{letter:"B",text:"Cross-cutting sustainability competencies embedded across all vocational programmes alongside specific green skills"},{letter:"C",text:"A single elective course on climate change"},{letter:"D",text:"Replacement of all technical subjects with ecology courses"}],answer:"B",feedback:"Effective green curricula integrate sustainability as a cross-cutting theme through all programmes, not just standalone electives, while also developing sector-specific technical green competencies."},
  {id:"week4_gen_24",text:"Which global report by UNEP first popularised the concept of the 'green economy' as a policy framework?",options:[{letter:"A",text:"Brundtland Report (1987)"},{letter:"B",text:"UNEP's Green Economy Report (2011)"},{letter:"C",text:"Stern Review on the Economics of Climate Change (2006)"},{letter:"D",text:"Rio+20 Conference Outcome Document (2012)"}],answer:"B",feedback:"UNEP's 2011 Green Economy Report — 'Towards a Green Economy: Pathways to Sustainable Development and Poverty Eradication' — was a landmark document that mainstreamed the green economy concept in international policy discourse."},
  {id:"week4_gen_25",text:"Which of the following is a characteristic of 'decent work' as defined by the ILO?",options:[{letter:"A",text:"Any employment regardless of safety or pay level"},{letter:"B",text:"Productive work under conditions of freedom, equity, security and human dignity"},{letter:"C",text:"Employment in high-technology industries only"},{letter:"D",text:"Work that is performed exclusively in formal sector enterprises"}],answer:"B",feedback:"The ILO defines decent work as productive work carried out in conditions of freedom, equity, security and human dignity — it encompasses formal and informal employment across all sectors."},
  {id:"week4_gen_26",text:"Which of the following practices is associated with the circular economy principle of 'narrowing resource loops'?",options:[{letter:"A",text:"Exporting waste to other countries for disposal"},{letter:"B",text:"Improving product efficiency and durability to reduce material throughput"},{letter:"C",text:"Increasing production speed to meet higher consumer demand"},{letter:"D",text:"Burning waste materials in incinerators to generate electricity"}],answer:"B",feedback:"Narrowing resource loops means using fewer resources per unit of output — achieved through efficiency gains, dematerialisation and product durability rather than more extraction."},
  {id:"week4_gen_27",text:"Sustainable entrepreneurship is often linked to which concept that measures business impact across economic, social and environmental dimensions?",options:[{letter:"A",text:"Return on investment (ROI)"},{letter:"B",text:"Triple bottom line (people, planet, profit)"},{letter:"C",text:"Net present value (NPV)"},{letter:"D",text:"Earnings before interest and tax (EBIT)"}],answer:"B",feedback:"The triple bottom line framework, coined by John Elkington, measures performance along three dimensions — people (social), planet (environmental) and profit (economic) — and is foundational to sustainable entrepreneurship."},
  {id:"week4_gen_28",text:"Which sector is projected to see the largest creation of green jobs globally according to ILO estimates?",options:[{letter:"A",text:"Agriculture and forestry"},{letter:"B",text:"Traditional manufacturing"},{letter:"C",text:"Renewable energy and energy efficiency"},{letter:"D",text:"Financial services"}],answer:"C",feedback:"ILO studies consistently show that renewable energy and energy efficiency sectors are among the largest generators of new green employment opportunities globally."},
  {id:"week4_gen_29",text:"The 'sharing economy' relates to the circular economy concept because it:",options:[{letter:"A",text:"Encourages greater individual ownership of goods"},{letter:"B",text:"Maximises product utilisation through shared access, reducing the need for new resource extraction"},{letter:"C",text:"Allows governments to share financial burdens with businesses"},{letter:"D",text:"Promotes free trade agreements between nations"}],answer:"B",feedback:"Sharing economy platforms (e.g., car-sharing, tool libraries) increase the use rate of existing goods, extending their effective life and reducing demand for new production — a circular economy principle."},
  {id:"week4_gen_30",text:"In sustainable entrepreneurship, 'opportunity recognition' often arises from:",options:[{letter:"A",text:"Identifying gaps in luxury goods markets"},{letter:"B",text:"Recognising unmet social or environmental needs that can be addressed through innovative market solutions"},{letter:"C",text:"Copying established business models from large corporations"},{letter:"D",text:"Government directives specifying which markets to enter"}],answer:"B",feedback:"Sustainable entrepreneurs are motivated by social or environmental problem-solving; they spot unmet needs — in underserved communities or degraded ecosystems — as entrepreneurial opportunities."},
  {id:"week4_gen_31",text:"Which of the following best illustrates 'eco-innovation at the system level'?",options:[{letter:"A",text:"A company switching from plastic to paper packaging"},{letter:"B",text:"A city redesigning its entire urban transport system to eliminate private car dependence through integrated cycling, walking and public transit"},{letter:"C",text:"A factory installing LED lighting to reduce electricity use"},{letter:"D",text:"A retailer launching a green product line"}],answer:"B",feedback:"System-level eco-innovation involves transforming entire socio-technical systems (e.g., urban mobility), not just improving individual products or processes within an existing system."},
  {id:"week4_gen_32",text:"Under SDG 8, 'productive employment' means:",options:[{letter:"A",text:"Employment in industries with the highest profit margins"},{letter:"B",text:"Work that generates sufficient income to allow individuals to live in dignity and contribute to economic growth"},{letter:"C",text:"Employment in manufacturing sectors only"},{letter:"D",text:"Any form of paid work, including exploitative labour"}],answer:"B",feedback:"Productive employment under SDG 8 implies work that is sufficiently remunerative and contributes to both individual welfare and broader economic productivity, paired with decent working conditions."},
  {id:"week4_gen_33",text:"The 'green economy' transition is expected to result in net job GAINS primarily because:",options:[{letter:"A",text:"Green industries are fully automated and require no human labour"},{letter:"B",text:"Labour-intensive activities like renewable energy installation, retrofitting and sustainable agriculture can create more jobs than fossil fuel industries displace"},{letter:"C",text:"Governments will pay all workers regardless of productivity"},{letter:"D",text:"Green jobs pay lower wages and therefore more can be created"}],answer:"B",feedback:"Analyses show that green transitions can produce net job gains: renewable energy, efficiency retrofitting and sustainable land management tend to be more labour-intensive than the industries they replace."},
  {id:"week4_gen_34",text:"Which of the following is a key barrier to greening TVET in developing countries?",options:[{letter:"A",text:"Excessive government funding for green skills training"},{letter:"B",text:"Shortage of qualified trainers with both technical and sustainability competencies, outdated curricula and limited green industry partnerships"},{letter:"C",text:"Too many students choosing green vocational programmes"},{letter:"D",text:"International organisations discouraging TVET investment"}],answer:"B",feedback:"In developing countries, greening TVET faces barriers including unqualified trainers, outdated content, weak industry-education linkages and insufficient funding for curriculum reform and green equipment."},
  {id:"week4_gen_35",text:"The circular economy concept of 'industrial symbiosis' refers to:",options:[{letter:"A",text:"Competing firms merging into one industrial giant"},{letter:"B",text:"A network of diverse companies that exchange materials, energy and by-products so that the waste of one becomes the resource of another"},{letter:"C",text:"Government subsidising all industrial enterprises equally"},{letter:"D",text:"Industries relocating to eco-industrial parks in rural areas"}],answer:"B",feedback:"Industrial symbiosis — exemplified by the Kalundborg Symbiosis in Denmark — is a collaborative system where firms exchange waste streams, reducing raw material consumption and disposal costs."},
  {id:"week4_gen_36",text:"Biomimicry as a form of eco-innovation involves:",options:[{letter:"A",text:"Using biological organisms to conduct laboratory experiments"},{letter:"B",text:"Designing products, processes and systems modelled on biological processes and strategies found in nature"},{letter:"C",text:"Replacing human workers with robotic systems inspired by animals"},{letter:"D",text:"Growing food inside factories to replace conventional agriculture"}],answer:"B",feedback:"Biomimicry draws lessons from 3.8 billion years of natural evolution; designers replicate nature's strategies (e.g., lotus-effect self-cleaning surfaces, termite mound ventilation) to create sustainable solutions."},
  {id:"week4_gen_37",text:"Which of the following statements about social enterprises is FALSE?",options:[{letter:"A",text:"They must demonstrate a clear social or environmental mission"},{letter:"B",text:"Their profits are primarily reinvested into the mission rather than distributed to shareholders"},{letter:"C",text:"They cannot generate any revenue through commercial activities"},{letter:"D",text:"They can operate across sectors including education, healthcare and environment"}],answer:"C",feedback:"Social enterprises are distinguished by their mission-driven use of revenue — but they absolutely do generate revenue through commercial activity; that is what makes them enterprises rather than charities."},
  {id:"week4_gen_38",text:"SDG 9 target 9.2 specifically calls for:",options:[{letter:"A",text:"Achieving universal primary education by 2030"},{letter:"B",text:"Promoting inclusive and sustainable industrialisation and significantly raising industry's share of employment and GDP in least developed countries"},{letter:"C",text:"Doubling renewable energy capacity globally"},{letter:"D",text:"Eliminating all forms of child labour"}],answer:"B",feedback:"SDG 9.2 aims to promote inclusive and sustainable industrialisation and significantly increase industry's share of employment and GDP, especially in least developed countries."},
  {id:"week4_gen_39",text:"'Leapfrogging' in the context of green industrialisation means:",options:[{letter:"A",text:"Skipping sustainable development stages to return to fossil fuels"},{letter:"B",text:"Developing nations bypassing carbon-intensive development pathways by adopting clean technologies directly"},{letter:"C",text:"Companies jumping from one industry to another without planning"},{letter:"D",text:"Governments ignoring international environmental commitments"}],answer:"B",feedback:"Leapfrogging allows developing countries to move straight to cleaner technologies (e.g., mobile banking over fixed-line banking; solar grids over coal grids) without replicating the carbon-intensive phase of industrialised nations."},
  {id:"week4_gen_40",text:"Which of the following BEST describes the relationship between TVET and SDG 8?",options:[{letter:"A",text:"TVET undermines SDG 8 by preparing workers for jobs that will be automated"},{letter:"B",text:"TVET contributes to SDG 8 by equipping people with vocational skills that enhance employability, productivity and access to decent work"},{letter:"C",text:"TVET is irrelevant to SDG 8 because SDG 8 only concerns macroeconomic policy"},{letter:"D",text:"TVET and SDG 8 are addressed by entirely separate international bodies with no linkage"}],answer:"B",feedback:"TVET is a direct enabler of SDG 8 — quality vocational training expands access to decent work, raises productivity, reduces unemployment and supports inclusive economic growth."},
  {id:"week4_gen_41",text:"The term 'green skills gap' refers to:",options:[{letter:"A",text:"The physical distance between green industries and TVET institutions"},{letter:"B",text:"The difference between the green competencies the economy requires and those that workers and graduates currently possess"},{letter:"C",text:"The funding shortfall in environmental research"},{letter:"D",text:"The lack of green spaces in urban areas"}],answer:"B",feedback:"The green skills gap is the mismatch between workforce competencies and the demands of a greener economy — a central concern in TVET policy and labour market planning."},
  {id:"week4_gen_42",text:"Which of the following is an example of 'upcycling' in the circular economy?",options:[{letter:"A",text:"Sending plastic waste to landfill"},{letter:"B",text:"Converting used tyres into high-value playground surfacing material, adding value rather than degrading the material"},{letter:"C",text:"Melting down metals and re-forming them into the same product"},{letter:"D",text:"Exporting second-hand clothes to other countries"}],answer:"B",feedback:"Upcycling transforms waste materials into products of higher quality or value than the original, in contrast to downcycling (which reduces quality) or simple recycling (same quality)."},
  {id:"week4_gen_43",text:"Green entrepreneurship is MOST closely associated with which type of innovation?",options:[{letter:"A",text:"Financial innovation targeting hedge funds"},{letter:"B",text:"Disruptive innovation that simultaneously creates market value and reduces environmental or social harm"},{letter:"C",text:"Incremental product improvements with no social dimension"},{letter:"D",text:"Process innovation focused solely on reducing labour costs"}],answer:"B",feedback:"Green entrepreneurs pursue innovations that disrupt existing unsustainable industries by offering solutions that are environmentally superior and economically viable."},
  {id:"week4_gen_44",text:"Which of the following is considered a 'soft' green skill?",options:[{letter:"A",text:"Operating solar panel installation equipment"},{letter:"B",text:"Conducting a life-cycle assessment"},{letter:"C",text:"Systems thinking and the ability to understand complex environmental interdependencies"},{letter:"D",text:"Managing hazardous waste disposal procedures"}],answer:"C",feedback:"Green skills include both technical (hard) skills — like LCA or equipment operation — and transversal (soft) skills such as systems thinking, collaborative problem-solving and ethical reasoning."},
  {id:"week4_gen_45",text:"The 'performance economy' model, associated with circular economy thinking, proposes that:",options:[{letter:"A",text:"Companies should compete solely on the basis of cost-cutting"},{letter:"B",text:"Manufacturers retain ownership of products and sell performance or outcomes to users rather than the products themselves"},{letter:"C",text:"Governments should manage all industrial production"},{letter:"D",text:"Economic performance should be measured only by GDP"}],answer:"B",feedback:"In the performance economy (developed by Walter Stahel), manufacturers sell outcomes (e.g., kilometres driven, lumens of light) rather than goods, incentivising durability, repair and resource efficiency."},
  {id:"week4_gen_46",text:"Under SDG 9, what does 'resilient infrastructure' specifically imply?",options:[{letter:"A",text:"Infrastructure built to withstand only military threats"},{letter:"B",text:"Infrastructure designed to be reliable, accessible and able to withstand economic, social and environmental shocks, including climate hazards"},{letter:"C",text:"Infrastructure that is exclusively owned by private investors"},{letter:"D",text:"Infrastructure built as quickly as possible without quality checks"}],answer:"B",feedback:"Resilient infrastructure under SDG 9 means infrastructure that can absorb and recover from shocks, is universally accessible, quality-built and aligned with sustainable development needs including climate adaptation."},
  {id:"week4_gen_47",text:"Which of the following metrics is most commonly used to assess the 'circularity' of an economy?",options:[{letter:"A",text:"GDP per capita"},{letter:"B",text:"Circularity Rate — the share of secondary (recycled/recovered) materials in total material input"},{letter:"C",text:"Inflation rate"},{letter:"D",text:"Foreign direct investment inflows"}],answer:"B",feedback:"The circularity rate (or circular material use rate) measures how much of material input to the economy comes from recovered/recycled sources, indicating how far an economy has moved from a linear model."},
  {id:"week4_gen_48",text:"Which of the following is an example of a TVET institution 'walking the talk' on sustainability?",options:[{letter:"A",text:"Increasing student enrolment numbers without changing teaching methods"},{letter:"B",text:"Installing solar panels on campus, composting food waste and integrating these campus systems as live learning laboratories for students"},{letter:"C",text:"Publishing a sustainability report without changing any campus practices"},{letter:"D",text:"Outsourcing all campus operations to private contractors"}],answer:"B",feedback:"TVET institutions that implement sustainability on their own campuses and use those systems as teaching resources model genuine integration of green principles into both practice and pedagogy."},
  {id:"week4_gen_49",text:"The concept of 'sustainable consumption and production' (SCP), relevant to TVET and the green economy, is addressed primarily under which SDG?",options:[{letter:"A",text:"SDG 7"},{letter:"B",text:"SDG 12"},{letter:"C",text:"SDG 15"},{letter:"D",text:"SDG 16"}],answer:"B",feedback:"SDG 12 — Responsible Consumption and Production — directly addresses SCP, calling for sustainable management of natural resources, reduction of waste and environmentally sound management of chemicals."}
];

const week5 = [
  {id:"week5_gen_0",text:"What does SDG 3 aim to achieve?",options:[{letter:"A",text:"Zero Hunger"},{letter:"B",text:"Quality Education"},{letter:"C",text:"Good Health and Well-Being for all at all ages"},{letter:"D",text:"Clean Water and Sanitation"}],answer:"C",feedback:"SDG 3 is 'Good Health and Well-Being,' aiming to ensure healthy lives and promote well-being for all at all ages."},
  {id:"week5_gen_1",text:"Universal Health Coverage (UHC) means that:",options:[{letter:"A",text:"Only wealthy citizens can access health services"},{letter:"B",text:"All people have access to quality health services they need without suffering financial hardship"},{letter:"C",text:"All countries adopt a single identical health system"},{letter:"D",text:"Governments provide unlimited funding for any health intervention"}],answer:"B",feedback:"UHC, a core target of SDG 3, ensures all people receive quality health services without being exposed to financial catastrophe — covering promotion, prevention, treatment and rehabilitation."},
  {id:"week5_gen_2",text:"Which of the following is classified as a non-communicable disease (NCD)?",options:[{letter:"A",text:"Tuberculosis"},{letter:"B",text:"Malaria"},{letter:"C",text:"Type 2 Diabetes"},{letter:"D",text:"Cholera"}],answer:"C",feedback:"Non-communicable diseases (NCDs) are chronic conditions not transmitted person-to-person; Type 2 diabetes is a leading NCD, unlike TB, malaria or cholera which are infectious/communicable."},
  {id:"week5_gen_3",text:"The four main behavioural risk factors for non-communicable diseases identified by the WHO are:",options:[{letter:"A",text:"Air pollution, unsafe water, poor housing and low income"},{letter:"B",text:"Tobacco use, harmful alcohol use, physical inactivity and unhealthy diets"},{letter:"C",text:"Lack of sleep, stress, poor hygiene and excessive screen time"},{letter:"D",text:"Genetic mutations, ageing, urbanisation and globalisation"}],answer:"B",feedback:"WHO identifies tobacco use, harmful use of alcohol, physical inactivity and unhealthy diets as the four modifiable behavioural risk factors driving the majority of NCDs globally."},
  {id:"week5_gen_4",text:"Social determinants of health are BEST described as:",options:[{letter:"A",text:"Individual genetic characteristics that predispose people to disease"},{letter:"B",text:"The medical treatments available in a country's health system"},{letter:"C",text:"The conditions in which people are born, grow, live, work and age that shape health outcomes"},{letter:"D",text:"The pharmaceutical drugs prescribed by doctors"}],answer:"C",feedback:"Social determinants of health — income, education, employment, housing, social support — are the non-medical factors in everyday environments that exert the strongest influence on health outcomes."},
  {id:"week5_gen_5",text:"Maternal mortality ratio is defined as:",options:[{letter:"A",text:"The number of deaths of children under 5 per 1,000 live births"},{letter:"B",text:"The number of maternal deaths per 100,000 live births"},{letter:"C",text:"The percentage of women who die from any cause during their lifetime"},{letter:"D",text:"The number of pregnancies ending in stillbirth per year"}],answer:"B",feedback:"Maternal mortality ratio (MMR) is the number of maternal deaths during pregnancy or within 42 days of termination per 100,000 live births — a key indicator under SDG 3."},
  {id:"week5_gen_6",text:"SDG 3 target 3.1 aims to reduce the global maternal mortality ratio to less than:",options:[{letter:"A",text:"500 per 100,000 live births"},{letter:"B",text:"70 per 100,000 live births"},{letter:"C",text:"10 per 100,000 live births"},{letter:"D",text:"200 per 100,000 live births"}],answer:"B",feedback:"SDG 3.1 targets reducing the global maternal mortality ratio to fewer than 70 maternal deaths per 100,000 live births by 2030."},
  {id:"week5_gen_7",text:"Under-5 mortality rate is a critical child health indicator. SDG 3.2 targets ending preventable deaths of newborns and children under 5 by reducing under-5 mortality to at most:",options:[{letter:"A",text:"10 per 1,000 live births"},{letter:"B",text:"25 per 1,000 live births"},{letter:"C",text:"50 per 1,000 live births"},{letter:"D",text:"100 per 1,000 live births"}],answer:"B",feedback:"SDG 3.2 aims to end preventable deaths of newborns and children under 5 years, with all countries targeting a reduction of under-5 mortality to at least as low as 25 per 1,000 live births by 2030."},
  {id:"week5_gen_8",text:"Which financing mechanism pools risks across populations to protect individuals from catastrophic out-of-pocket health expenditure?",options:[{letter:"A",text:"User fees"},{letter:"B",text:"Health insurance (social or community-based)"},{letter:"C",text:"Direct patient payments at the point of care"},{letter:"D",text:"Medical tourism"}],answer:"B",feedback:"Health insurance — whether social (tax or payroll-funded) or community-based — pools risk so that individuals do not face catastrophic costs when they need care, a key mechanism for achieving UHC."},
  {id:"week5_gen_9",text:"The WHO's primary role in global health governance includes:",options:[{letter:"A",text:"Operating hospitals directly in member countries"},{letter:"B",text:"Setting international health standards, coordinating responses to global health emergencies and providing technical assistance to countries"},{letter:"C",text:"Funding all health expenditure in low-income countries"},{letter:"D",text:"Approving pharmaceutical products for sale in all countries"}],answer:"B",feedback:"WHO's mandate is to provide leadership on global health matters, set norms and standards, monitor health trends, coordinate emergency responses and support countries in strengthening health systems."},
  {id:"week5_gen_10",text:"Primary health care (PHC) as a foundation for UHC emphasises:",options:[{letter:"A",text:"Specialist hospital care as the first point of contact"},{letter:"B",text:"Essential, community-based health services that address the leading causes of illness and death, with communities as active participants"},{letter:"C",text:"Treatment of only life-threatening conditions in tertiary hospitals"},{letter:"D",text:"Health care exclusively for working-age adults"}],answer:"B",feedback:"The Alma-Ata Declaration (1978) and the Astana Declaration (2018) affirm that PHC — accessible, comprehensive community-based care involving communities — is the most effective way to achieve UHC."},
  {id:"week5_gen_11",text:"Which of the following is a 'communicable' (infectious) disease still targeted under SDG 3?",options:[{letter:"A",text:"Cardiovascular disease"},{letter:"B",text:"HIV/AIDS"},{letter:"C",text:"Chronic obstructive pulmonary disease"},{letter:"D",text:"Alzheimer's disease"}],answer:"B",feedback:"SDG 3 targets ending the epidemics of AIDS, tuberculosis, malaria and neglected tropical diseases — all communicable diseases — by 2030, alongside reducing premature mortality from NCDs."},
  {id:"week5_gen_12",text:"'Out-of-pocket' health expenditure is most problematic because:",options:[{letter:"A",text:"It makes health systems more efficient"},{letter:"B",text:"It can push households into poverty when they face serious illness, creating a financial barrier to care"},{letter:"C",text:"It discourages unnecessary use of health services"},{letter:"D",text:"It is the preferred funding mechanism for high-income countries"}],answer:"B",feedback:"High out-of-pocket spending forces families — especially poor ones — to choose between healthcare and other needs, often leading to catastrophic expenditure, impoverishment or foregone care."},
  {id:"week5_gen_13",text:"The 'health workforce crisis' refers to a situation where:",options:[{letter:"A",text:"Health workers earn too high a salary"},{letter:"B",text:"There is a critical shortage of skilled health workers in many countries, especially low-income ones, undermining health system performance"},{letter:"C",text:"Too many doctors are trained, leading to unemployment"},{letter:"D",text:"Health workers refuse to use digital health technologies"}],answer:"B",feedback:"The WHO estimates a global shortage of millions of health workers, concentrated in low- and middle-income countries, severely limiting the ability to achieve UHC and SDG 3 targets."},
  {id:"week5_gen_14",text:"Food security, relevant to health outcomes under SDG 2 and SDG 3, exists when:",options:[{letter:"A",text:"A country produces all its own food domestically"},{letter:"B",text:"All people, at all times, have physical, social and economic access to sufficient, safe and nutritious food that meets their dietary needs and food preferences for an active and healthy life"},{letter:"C",text:"Food prices are kept artificially low by government subsidies"},{letter:"D",text:"Food is equally distributed among all citizens regardless of income"}],answer:"B",feedback:"The 1996 World Food Summit definition of food security encompasses the four pillars: availability, access, utilisation and stability — all people must be able to access adequate, safe, nutritious food at all times."},
  {id:"week5_gen_15",text:"The 'double burden of malnutrition' describes a situation where:",options:[{letter:"A",text:"Two separate countries both face malnutrition simultaneously"},{letter:"B",text:"The same population or household experiences both undernutrition (stunting, wasting, deficiencies) and overnutrition (obesity, diet-related NCDs) simultaneously"},{letter:"C",text:"Children suffer from malnutrition twice in their life"},{letter:"D",text:"A government must fund both food aid and agriculture simultaneously"}],answer:"B",feedback:"The double burden of malnutrition — now common in middle-income countries — means communities face concurrent problems of hunger/micronutrient deficiency and overweight/obesity-related NCDs."},
  {id:"week5_gen_16",text:"SDG 2 food security targets include ending hunger and ensuring access to safe, nutritious food for all by:",options:[{letter:"A",text:"2020"},{letter:"B",text:"2025"},{letter:"C",text:"2030"},{letter:"D",text:"2050"}],answer:"C",feedback:"SDG 2 aims to end hunger, achieve food security and improved nutrition and promote sustainable agriculture by 2030, consistent with the overall 2030 Agenda for Sustainable Development."},
  {id:"week5_gen_17",text:"Stunting in children (low height-for-age) is primarily caused by:",options:[{letter:"A",text:"Excessive physical activity in early childhood"},{letter:"B",text:"Chronic undernutrition and inadequate nutrition and care during the first 1,000 days of life (conception to age 2)"},{letter:"C",text:"Genetic factors that cannot be influenced by nutrition"},{letter:"D",text:"Over-vaccination in infancy"}],answer:"B",feedback:"Stunting results from chronic inadequate nutrition and poor feeding practices, particularly during the critical window of the first 1,000 days; it has lasting effects on physical and cognitive development."},
  {id:"week5_gen_18",text:"The concept of 'health equity' means:",options:[{letter:"A",text:"All people receive identical health treatments regardless of need"},{letter:"B",text:"Health resources and health outcomes are distributed fairly, addressing differences in health status that are avoidable and unjust"},{letter:"C",text:"Health outcomes are determined purely by individual choices"},{letter:"D",text:"All countries have equal health budgets"}],answer:"B",feedback:"Health equity implies that unjust, preventable health differences between social groups are reduced; it requires proportionate resource allocation to address greater need in disadvantaged populations."},
  {id:"week5_gen_19",text:"Which institution manages the Global Fund for AIDS, Tuberculosis and Malaria?",options:[{letter:"A",text:"The World Bank"},{letter:"B",text:"UNICEF"},{letter:"C",text:"The Global Fund — an independent international financing institution"},{letter:"D",text:"WHO"}],answer:"C",feedback:"The Global Fund to Fight AIDS, Tuberculosis and Malaria is an independent international financing organisation that mobilises and invests resources to fight the three diseases, and is distinct from WHO or the World Bank."},
  {id:"week5_gen_20",text:"The 'epidemiological transition' describes a shift in disease patterns from:",options:[{letter:"A",text:"Urban to rural disease distribution"},{letter:"B",text:"Communicable diseases dominating causes of death to chronic non-communicable diseases becoming predominant"},{letter:"C",text:"Childhood diseases to adult diseases regardless of type"},{letter:"D",text:"Environmental to genetic causes of disease"}],answer:"B",feedback:"The epidemiological transition, observed as countries develop, involves a decline in infectious disease mortality and a rise in NCDs (cardiovascular disease, cancer, diabetes) as the leading causes of death and disability."},
  {id:"week5_gen_21",text:"SDG 3.4 aims to reduce premature mortality from NCDs by what fraction by 2030?",options:[{letter:"A",text:"One quarter"},{letter:"B",text:"One third"},{letter:"C",text:"One half"},{letter:"D",text:"Three quarters"}],answer:"B",feedback:"SDG 3.4 calls for a one-third reduction in premature mortality from NCDs (cardiovascular diseases, cancer, diabetes, chronic respiratory diseases) through prevention and treatment by 2030."},
  {id:"week5_gen_22",text:"The Sustainable Development Goal indicator for UHC progress is the:",options:[{letter:"A",text:"Number of hospitals per 1,000 people"},{letter:"B",text:"UHC Service Coverage Index — a composite index of essential health service coverage"},{letter:"C",text:"Total health expenditure as a percentage of GDP"},{letter:"D",text:"Number of doctors per capita"}],answer:"B",feedback:"The UHC Service Coverage Index (SDG indicator 3.8.1) tracks coverage of essential health services across reproductive/maternal health, child health, infectious diseases and service capacity, on a scale of 0-100."},
  {id:"week5_gen_23",text:"'Health literacy' is best defined as:",options:[{letter:"A",text:"The ability to read and write in a medical setting"},{letter:"B",text:"The degree to which individuals can obtain, process and understand basic health information and services to make appropriate health decisions"},{letter:"C",text:"A doctor's knowledge of medical literature"},{letter:"D",text:"Government publication of health statistics"}],answer:"B",feedback:"Health literacy — the capacity to find, understand and use health information — is a key determinant of health behaviour and outcomes, influencing how people navigate health systems."},
  {id:"week5_gen_24",text:"Which of the following BEST describes the 'social gradient in health'?",options:[{letter:"A",text:"People at all social levels have equal health outcomes"},{letter:"B",text:"Health outcomes improve progressively as socio-economic status increases, forming a gradient across the whole social spectrum"},{letter:"C",text:"Only the very poor have worse health than the rest of society"},{letter:"D",text:"Social factors have no influence on health outcomes"}],answer:"B",feedback:"The social gradient shows that health worsens progressively as one moves down the socioeconomic ladder — it is not just about poverty at the bottom but a gradient affecting every rung."},
  {id:"week5_gen_25",text:"The 'Alma-Ata Declaration' of 1978 is historically significant in global health because it:",options:[{letter:"A",text:"Established the WHO as the lead global health agency"},{letter:"B",text:"Proclaimed 'Health for All' through primary health care as a fundamental human right and a political commitment"},{letter:"C",text:"Launched the first global vaccination campaign"},{letter:"D",text:"Created the Global Fund to fight infectious diseases"}],answer:"B",feedback:"The 1978 International Conference on Primary Health Care at Alma-Ata produced a landmark declaration affirming health as a fundamental right and establishing primary health care as the pathway to 'Health for All.'"},
  {id:"week5_gen_26",text:"Which of the following is a key challenge to achieving UHC in low-income countries?",options:[{letter:"A",text:"Excessive public funding for health services"},{letter:"B",text:"High reliance on out-of-pocket payments, inadequate health workforce, fragile health infrastructure and low fiscal capacity"},{letter:"C",text:"Too many trained health professionals who are overpaid"},{letter:"D",text:"Low demand for health services among populations"}],answer:"B",feedback:"Low-income countries face structural barriers to UHC: insufficient tax revenues, high OOP spending, critical health worker shortages, weak supply chains and inadequate health information systems."},
  {id:"week5_gen_27",text:"The WHO's concept of 'health systems building blocks' includes which of the following?",options:[{letter:"A",text:"Military defence, economic growth, education and housing"},{letter:"B",text:"Service delivery, health workforce, health information, medical products/technologies, financing and leadership/governance"},{letter:"C",text:"GDP growth, trade, foreign investment and technology transfer"},{letter:"D",text:"Hospitals, doctors, nurses and pharmacists only"}],answer:"B",feedback:"WHO's health systems framework identifies six building blocks: service delivery; health workforce; health information systems; medical products and technologies; health financing; and leadership/governance."},
  {id:"week5_gen_28",text:"Wasting in children (low weight-for-height) is typically a sign of:",options:[{letter:"A",text:"Chronic, long-term undernutrition over years"},{letter:"B",text:"Acute, recent food deprivation or illness causing rapid weight loss"},{letter:"C",text:"Normal childhood growth variation"},{letter:"D",text:"Excessive physical exercise"}],answer:"B",feedback:"Wasting reflects acute malnutrition — a recent, severe nutritional deficit often due to food shortage or illness; it is associated with high risk of mortality and differs from stunting (chronic)."},
  {id:"week5_gen_29",text:"The Lancet Commission on Nutrition identified what as a major driver of all forms of malnutrition?",options:[{letter:"A",text:"Climate change only"},{letter:"B",text:"The 'syndemic' interaction of obesity, undernutrition and climate change as deeply interconnected global crises requiring joined-up solutions"},{letter:"C",text:"Lack of micronutrient supplements"},{letter:"D",text:"Poor individual dietary choices alone"}],answer:"B",feedback:"The 2019 Lancet Commission on Obesity coined the term 'global syndemic' to describe the interaction of obesity, undernutrition and climate change — arguing that these three crises share common drivers and must be tackled together."},
  {id:"week5_gen_30",text:"SDG 3.b calls for access to affordable essential medicines and vaccines, which is linked to which international agreement?",options:[{letter:"A",text:"The Kyoto Protocol"},{letter:"B",text:"The TRIPS Agreement (Trade-Related Aspects of Intellectual Property Rights) and the Doha Declaration on TRIPS and Public Health"},{letter:"C",text:"The Basel Convention"},{letter:"D",text:"The Paris Agreement"}],answer:"B",feedback:"SDG 3.b recognises the tension between intellectual property rights (TRIPS) and access to medicines; the 2001 Doha Declaration affirmed that countries can override patents for public health emergencies."},
  {id:"week5_gen_31",text:"Global health governance is challenged by the 'global health security' problem because:",options:[{letter:"A",text:"All countries have agreed on a single global health strategy"},{letter:"B",text:"Infectious diseases do not respect national borders, meaning a health crisis in one country can rapidly become a global threat, requiring coordinated international responses"},{letter:"C",text:"Health systems are too strong to allow disease spread"},{letter:"D",text:"Only tropical diseases pose international risks"}],answer:"B",feedback:"Global health security addresses the collective vulnerability of all countries to transboundary health threats; as demonstrated by COVID-19, Ebola and influenza, disease outbreaks require coordinated international surveillance and response."},
  {id:"week5_gen_32",text:"The International Health Regulations (IHR 2005) require member states to:",options:[{letter:"A",text:"Provide equal health services to all citizens"},{letter:"B",text:"Develop core public health capacities for surveillance and response to public health emergencies of international concern (PHEICs)"},{letter:"C",text:"Spend at least 5% of GDP on health"},{letter:"D",text:"Share all health data openly with all countries without restriction"}],answer:"B",feedback:"The IHR (2005) is a legally binding WHO instrument requiring 196 countries to build national surveillance and response capacities to detect, assess, notify and respond to public health events."},
  {id:"week5_gen_33",text:"Which of the following BEST illustrates the concept of 'health as a human right'?",options:[{letter:"A",text:"Governments may choose to provide health services as a discretionary benefit"},{letter:"B",text:"Every person is entitled to the highest attainable standard of health, and states have obligations to respect, protect and fulfil this right without discrimination"},{letter:"C",text:"Only citizens of wealthy nations can claim a right to health"},{letter:"D",text:"Health rights apply only to communicable disease prevention"}],answer:"B",feedback:"Article 12 of the International Covenant on Economic, Social and Cultural Rights recognises the right of everyone to the highest attainable standard of physical and mental health — an obligation that states must work progressively to fulfil."},
  {id:"week5_gen_34",text:"Under-nutrition in pregnant women is particularly harmful because it:",options:[{letter:"A",text:"Only affects the mother's health, not the child"},{letter:"B",text:"Increases risk of low birth weight, preterm birth and intergenerational malnutrition, affecting child development for life"},{letter:"C",text:"Has no long-term consequences if corrected after birth"},{letter:"D",text:"Is a natural condition that does not require intervention"}],answer:"B",feedback:"Maternal undernutrition causes low birth weight, weakened immune function and impaired cognitive development; it perpetuates an intergenerational cycle of malnutrition and poverty."},
  {id:"week5_gen_35",text:"'Catastrophic health expenditure' is typically defined as out-of-pocket health spending exceeding:",options:[{letter:"A",text:"1% of household income or consumption"},{letter:"B",text:"10% of total household consumption (or 25% of non-food consumption)"},{letter:"C",text:"50% of household savings"},{letter:"D",text:"Any amount not covered by insurance"}],answer:"B",feedback:"WHO and World Bank commonly define catastrophic health expenditure as OOP payments that exceed 10% of total household consumption (or 25% of non-food expenditure), reflecting a threshold at which care imposes serious financial hardship."},
  {id:"week5_gen_36",text:"Which of the following is a strategy for strengthening health systems to achieve SDG 3?",options:[{letter:"A",text:"Reducing community participation in health service design"},{letter:"B",text:"Investing in community health workers, expanding health insurance coverage, improving drug supply chains and using digital health tools"},{letter:"C",text:"Concentrating all health resources in national capital cities"},{letter:"D",text:"Privatising all health services to increase efficiency"}],answer:"B",feedback:"Effective health system strengthening requires multiple strategies: training community health workers, expanding coverage through insurance, securing medicines and vaccines, and leveraging digital health — not just facility construction."},
  {id:"week5_gen_37",text:"What is the significance of the '1,000 days' in nutrition and child health?",options:[{letter:"A",text:"The period from a child's birth to their third birthday is when MCH interventions are least effective"},{letter:"B",text:"The window from conception to a child's second birthday is the most critical period for nutritional investment, with lasting impacts on brain development, growth and long-term health"},{letter:"C",text:"The first 1,000 days refers to the first three years of primary school education"},{letter:"D",text:"It is the duration of the standard maternal health programme recommended by WHO"}],answer:"B",feedback:"The 1,000 days window (pregnancy to age 2) is the most critical for nutrition; adequate nutrients during this period build lifelong cognitive and physical capacity, while deficits cause irreversible damage."},
  {id:"week5_gen_38",text:"Global health financing from donors flows primarily through which mechanisms?",options:[{letter:"A",text:"Bilateral official development assistance (ODA), multilateral funds (Global Fund, Gavi) and foundations (e.g., Bill & Melinda Gates Foundation)"},{letter:"B",text:"Direct cash transfers to individual patients"},{letter:"C",text:"Private pharmaceutical company grants only"},{letter:"D",text:"Tourist taxation in low-income countries"}],answer:"A",feedback:"Global health aid flows through bilateral ODA from donor governments, multilateral financing institutions and specialised health funds (Global Fund, Gavi) and large philanthropic foundations."},
  {id:"week5_gen_39",text:"Non-communicable diseases are now responsible for approximately what proportion of global deaths?",options:[{letter:"A",text:"20%"},{letter:"B",text:"40%"},{letter:"C",text:"55%"},{letter:"D",text:"Over 70%"}],answer:"D",feedback:"NCDs — primarily cardiovascular diseases, cancers, chronic respiratory diseases and diabetes — account for over 70% of all deaths globally, making them the leading cause of premature mortality worldwide."},
  {id:"week5_gen_40",text:"The 'Health in All Policies' (HiAP) approach calls for:",options:[{letter:"A",text:"Restricting health decision-making to the Ministry of Health"},{letter:"B",text:"Systematically considering the health implications of decisions across all sectors and policy areas, recognising that health is shaped by education, transport, housing, agriculture and other policy domains"},{letter:"C",text:"Making health the only priority in national budgets"},{letter:"D",text:"Replacing social policies with health insurance programmes"}],answer:"B",feedback:"HiAP recognises that health is produced outside the health sector; transport, urban planning, education, agriculture and environment policies all profoundly affect population health and must be designed with health in mind."},
  {id:"week5_gen_41",text:"Which of the following correctly pairs a major health challenge with its SDG 3 target?",options:[{letter:"A",text:"SDG 3.3 — Reducing premature NCD mortality"},{letter:"B",text:"SDG 3.3 — Ending the epidemics of AIDS, TB, malaria and neglected tropical diseases"},{letter:"C",text:"SDG 3.4 — Achieving universal health coverage"},{letter:"D",text:"SDG 3.8 — Ensuring access to safe water"}],answer:"B",feedback:"SDG 3.3 specifically targets ending the epidemics of AIDS, tuberculosis, malaria and neglected tropical diseases by 2030. SDG 3.4 targets NCD premature mortality reduction, and 3.8 covers UHC."},
  {id:"week5_gen_42",text:"'Brain drain' of health workers from low-income to high-income countries is problematic because:",options:[{letter:"A",text:"It benefits low-income countries through remittances sent home by migrant workers"},{letter:"B",text:"It depletes already scarce health workforces in countries with the greatest health burden, worsening health system capacity and equity"},{letter:"C",text:"High-income countries then have too many health workers"},{letter:"D",text:"It has no impact on health outcomes in either country"}],answer:"B",feedback:"When trained nurses and doctors emigrate from low-income countries (which subsidised their training) to higher-paying high-income countries, it exacerbates workforce shortages in the most health-burdened settings."},
  {id:"week5_gen_43",text:"Mental health is now recognised under SDG 3.4, which includes a target to:",options:[{letter:"A",text:"Eradicate all mental health conditions by 2030"},{letter:"B",text:"Promote mental health and well-being and strengthen prevention and treatment of substance abuse"},{letter:"C",text:"Replace mental health services with community policing"},{letter:"D",text:"Provide free psychotherapy to all citizens worldwide"}],answer:"B",feedback:"SDG 3.4 includes mental health and well-being promotion and calls for prevention and treatment of substance use disorders alongside the one-third reduction target for premature NCD mortality."},
  {id:"week5_gen_44",text:"The WHO's 'essential medicines' concept supports UHC by:",options:[{letter:"A",text:"Listing only expensive patented drugs that governments must purchase"},{letter:"B",text:"Identifying a core set of medicines that address priority health needs, are cost-effective and should be universally available and affordable"},{letter:"C",text:"Prohibiting countries from manufacturing generic drugs"},{letter:"D",text:"Ensuring pharmaceutical companies can charge premium prices"}],answer:"B",feedback:"The WHO Model List of Essential Medicines identifies medicines that satisfy the priority health-care needs of populations; they should be available in adequate amounts, appropriate dosage forms, with assured quality and at affordable prices."},
  {id:"week5_gen_45",text:"'Antenatal care' (ANC) is important for maternal and child health because:",options:[{letter:"A",text:"It is only needed for high-risk pregnancies"},{letter:"B",text:"Regular ANC visits allow early detection and management of complications, nutritional supplementation, tetanus vaccination and birth planning, reducing maternal and neonatal mortality"},{letter:"C",text:"ANC is optional and has limited impact on birth outcomes"},{letter:"D",text:"ANC replaces the need for skilled birth attendance"}],answer:"B",feedback:"At least four (now recommended eight) ANC contacts allow screening for pre-eclampsia, anaemia, infections and gestational diabetes; they also deliver iron/folate, vaccines and counselling — significantly reducing maternal and newborn mortality."},
  {id:"week5_gen_46",text:"The 'primary health care' (PHC) approach is distinguished from the 'selective primary health care' approach in that:",options:[{letter:"A",text:"PHC focuses on a narrow set of cost-effective interventions while selective PHC is comprehensive"},{letter:"B",text:"Comprehensive PHC addresses the broad range of health needs of communities, while selective PHC focuses on a limited package of targeted interventions"},{letter:"C",text:"PHC is only suitable for high-income countries"},{letter:"D",text:"There is no practical difference between the two approaches"}],answer:"B",feedback:"The PHC vs selective PHC debate is important: comprehensive PHC (Alma-Ata vision) addresses social determinants and community participation, while selective PHC narrows to specific high-impact interventions — both have different equity and sustainability implications."},
  {id:"week5_gen_47",text:"Which of the following BEST describes the relationship between education and health outcomes?",options:[{letter:"A",text:"Education has no proven relationship with health"},{letter:"B",text:"Higher levels of education are consistently associated with better health literacy, healthier behaviours, higher income and better health outcomes across the life course"},{letter:"C",text:"Education only affects mental health, not physical health"},{letter:"D",text:"The relationship between education and health is limited to high-income settings"}],answer:"B",feedback:"Education is one of the most powerful social determinants of health: it builds health literacy, increases income (reducing poverty), empowers women and shapes behaviours — improving health outcomes across all contexts."},
  {id:"week5_gen_48",text:"SDG 3.c calls for substantially increasing health financing and the recruitment and training of the health workforce in developing countries. This is critical because:",options:[{letter:"A",text:"Developing countries already have surplus health workers"},{letter:"B",text:"The WHO estimated a global shortage of 18 million health workers by 2030, concentrated in low- and middle-income countries, threatening UHC progress"},{letter:"C",text:"Health workers in developing countries are overpaid relative to their productivity"},{letter:"D",text:"Developing countries spend too much on health and need to reduce spending"}],answer:"B",feedback:"SDG 3.c directly addresses the health workforce crisis; WHO projects an 18 million health worker shortage by 2030, mostly in LMICs, making investment in training and retention essential for UHC."},
  {id:"week5_gen_49",text:"The concept of 'health as a public good' implies that:",options:[{letter:"A",text:"Health care should be privately provided and priced by the market"},{letter:"B",text:"Population health has characteristics of a public good — non-exclusion and non-rivalry in some dimensions — justifying collective action and public funding to prevent market failures"},{letter:"C",text:"Public parks are important for health"},{letter:"D",text:"Only governments, not individuals, are responsible for health"}],answer:"B",feedback:"While individual health services have private good characteristics, population health (e.g., disease control, vaccination herd immunity) has public good features — market failures justify collective investment and regulation."}
];

const week6 = [
  {id:"week6_gen_0",text:"SDG 2 calls for 'Zero Hunger.' Which of the following is NOT one of its main targets?",options:[{letter:"A",text:"End hunger and ensure access to safe, nutritious food for all"},{letter:"B",text:"End all forms of malnutrition by 2030"},{letter:"C",text:"Eliminate all forms of international food trade by 2030"},{letter:"D",text:"Ensure sustainable food production systems and resilient agricultural practices"}],answer:"C",feedback:"SDG 2 targets ending hunger, ending malnutrition and promoting sustainable agriculture; it does not call for eliminating food trade, which remains an important mechanism for food security."},
  {id:"week6_gen_1",text:"Agroecology is best described as:",options:[{letter:"A",text:"Large-scale monoculture farming using maximum chemical inputs"},{letter:"B",text:"An approach that applies ecological concepts and principles to the design and management of food systems, integrating traditional knowledge and minimising external inputs"},{letter:"C",text:"Hydroponic crop production in urban settings only"},{letter:"D",text:"A government agricultural subsidy programme"}],answer:"B",feedback:"Agroecology applies ecological science to farming: it values biodiversity, soil health, traditional knowledge and reduced dependence on synthetic inputs, creating resilient and sustainable food systems."},
  {id:"week6_gen_2",text:"Conservation agriculture is characterised by which three principles?",options:[{letter:"A",text:"Maximum tillage, monoculture and frequent irrigation"},{letter:"B",text:"Minimum tillage/soil disturbance, permanent soil cover and crop diversification/rotation"},{letter:"C",text:"Heavy use of pesticides, deep ploughing and single-crop systems"},{letter:"D",text:"Burning crop residues, flood irrigation and hybrid seed use"}],answer:"B",feedback:"Conservation agriculture (CA) rests on three principles: minimal mechanical soil disturbance (no or reduced tillage), permanent organic soil cover, and crop species diversification — together these protect soil health and reduce erosion."},
  {id:"week6_gen_3",text:"A food value chain describes:",options:[{letter:"A",text:"The nutritional content of food items"},{letter:"B",text:"The full range of activities from production (farm) to consumption (fork), including processing, packaging, distribution, retail and disposal"},{letter:"C",text:"The financial value of food exports from a country"},{letter:"D",text:"A chain of restaurants serving the same food items"}],answer:"B",feedback:"A food value chain captures all the actors, activities and value-adding steps from farm to fork — understanding it is essential for identifying where food is lost, where value accrues and how to make systems more equitable and sustainable."},
  {id:"week6_gen_4",text:"Approximately one-third of all food produced globally is:",options:[{letter:"A",text:"Traded on international commodity markets"},{letter:"B",text:"Lost or wasted along the food value chain"},{letter:"C",text:"Consumed by animals as feed"},{letter:"D",text:"Exported from developing to developed countries"}],answer:"B",feedback:"The UN FAO estimates that approximately 1.3 billion tonnes of food — roughly one-third of global production — is lost or wasted each year, representing a massive waste of resources and a major contributor to GHG emissions."},
  {id:"week6_gen_5",text:"'Food loss' differs from 'food waste' in that:",options:[{letter:"A",text:"Food loss is a deliberate act while food waste is accidental"},{letter:"B",text:"Food loss occurs earlier in the supply chain (production, post-harvest, processing) while food waste typically occurs at the retail and consumer end"},{letter:"C",text:"Food loss only occurs in developing countries while food waste only occurs in developed countries"},{letter:"D",text:"They are interchangeable terms with no meaningful distinction"}],answer:"B",feedback:"Food loss refers to quantity or quality reductions from harvest through processing (common in lower-income contexts); food waste refers to discarding of edible food at retail and consumption stages (more common in higher-income contexts)."},
  {id:"week6_gen_6",text:"Smallholder farmers are defined as:",options:[{letter:"A",text:"Farmers who grow only small-seeded crops"},{letter:"B",text:"Farm households managing small plots of land (typically under 2 hectares), often relying on family labour, and representing the majority of farms globally"},{letter:"C",text:"Farmers who sell exclusively in local markets"},{letter:"D",text:"Agricultural labourers employed by large agribusinesses"}],answer:"B",feedback:"Smallholder farmers — typically farming under 2 hectares with family labour — represent over 500 million farms globally and produce a large share of food in developing countries; they are central to both food security and rural poverty debates."},
  {id:"week6_gen_7",text:"Which of the following is a key challenge faced by smallholder farmers in developing countries?",options:[{letter:"A",text:"Access to too much credit and excessive market power"},{letter:"B",text:"Limited access to credit, markets, inputs, extension services and secure land tenure"},{letter:"C",text:"Overproduction leading to unsustainable surpluses"},{letter:"D",text:"Government policies exclusively favouring small-scale farming"}],answer:"B",feedback:"Smallholders face multiple constraints: poor market access, inability to access affordable credit, insufficient extension support, vulnerability to climate shocks and insecure land rights — all limiting productivity and income."},
  {id:"week6_gen_8",text:"Land rights are critical for food security because:",options:[{letter:"A",text:"Farmers with secure land tenure are more likely to invest in long-term soil improvements, access credit and increase productivity"},{letter:"B",text:"Land registration eliminates all forms of land disputes"},{letter:"C",text:"Large landowners always produce more food per hectare than smallholders"},{letter:"D",text:"Land rights are only relevant to urban housing policy"}],answer:"A",feedback:"Security of land tenure incentivises farmers to invest in soil health and productive capacity, access collateral-based credit and resist eviction; it is fundamentally linked to food security, especially for women and marginalised communities."},
  {id:"week6_gen_9",text:"The 'Green Revolution' of the 1960s-70s increased food production but also raised sustainability concerns because it:",options:[{letter:"A",text:"Promoted traditional diverse farming practices"},{letter:"B",text:"Led to dependence on high-yielding hybrid seeds requiring significant chemical fertilisers and irrigation, contributing to soil degradation, water depletion and loss of agricultural biodiversity"},{letter:"C",text:"Eliminated the use of synthetic fertilisers"},{letter:"D",text:"Was implemented exclusively in African countries"}],answer:"B",feedback:"The Green Revolution boosted cereal yields through high-response varieties, irrigation and agrochemicals but created ecological consequences: groundwater depletion, soil salinisation, biodiversity loss and chemical dependency."},
  {id:"week6_gen_10",text:"Seed diversity (agrobiodiversity) is important for food security because:",options:[{letter:"A",text:"More seed varieties makes farming more complex without benefit"},{letter:"B",text:"A diverse portfolio of crop varieties provides resilience against pests, diseases and climate change, and supports nutritional diversity"},{letter:"C",text:"Commercial seed companies cannot profit from diverse seed systems"},{letter:"D",text:"Governments prefer uniform crops for easier taxation"}],answer:"B",feedback:"Agrobiodiversity — maintained largely by indigenous and smallholder farmers — provides the genetic pool for adapting crops to changing conditions; monoculture dependence on few varieties creates vulnerability to catastrophic crop failure."},
  {id:"week6_gen_11",text:"Climate-smart agriculture (CSA) aims to achieve which THREE objectives simultaneously?",options:[{letter:"A",text:"Maximum yield, lowest cost and highest export volume"},{letter:"B",text:"Sustainably increasing agricultural productivity, adapting and building resilience to climate change, and reducing greenhouse gas emissions where possible"},{letter:"C",text:"Eliminating small farms, industrialising food production and maximising caloric output"},{letter:"D",text:"Replacing chemical farming with organic farming in all contexts"}],answer:"B",feedback:"CSA, promoted by FAO, targets three pillars: productivity (food security), adaptation (resilience to climate shocks) and mitigation (reducing agricultural GHG emissions) — recognising that these must be pursued together."},
  {id:"week6_gen_12",text:"Water use in agriculture globally accounts for approximately:",options:[{letter:"A",text:"20% of all freshwater withdrawals"},{letter:"B",text:"40% of all freshwater withdrawals"},{letter:"C",text:"70% of all freshwater withdrawals"},{letter:"D",text:"90% of all freshwater withdrawals"}],answer:"C",feedback:"Agriculture accounts for approximately 70% of global freshwater withdrawals, making it by far the largest user of freshwater — a major pressure on water resources especially in water-scarce regions."},
  {id:"week6_gen_13",text:"Drip irrigation is considered a water-smart agricultural practice because:",options:[{letter:"A",text:"It uses more water than flood irrigation to ensure crops are well-watered"},{letter:"B",text:"It delivers water directly to plant root zones, reducing evaporation and run-off and using up to 90% less water than conventional flood irrigation"},{letter:"C",text:"It is only suitable for large-scale commercial farms"},{letter:"D",text:"It requires no maintenance and works in any soil type"}],answer:"B",feedback:"Drip (trickle) irrigation delivers water precisely to roots, dramatically reducing wastage through evaporation and surface run-off; it can cut water use by 30-60% compared to furrow irrigation."},
  {id:"week6_gen_14",text:"The concept of 'food sovereignty' goes beyond food security by emphasising:",options:[{letter:"A",text:"A nation's right to produce all its food domestically and ban imports"},{letter:"B",text:"The right of peoples and nations to define their own food and agriculture policies, prioritising local production, cultural food traditions and democratic control over food systems"},{letter:"C",text:"Corporate control of global food supply chains for efficiency"},{letter:"D",text:"Free-market pricing for all agricultural commodities"}],answer:"B",feedback:"Food sovereignty, advocated by La Vía Campesina, argues that communities and nations — not corporations or markets — should control food systems, emphasising cultural rights, agroecology and farmer-centred approaches."},
  {id:"week6_gen_15",text:"In sustainable agriculture, 'integrated pest management' (IPM) refers to:",options:[{letter:"A",text:"Using maximum amounts of pesticide to eliminate all pests"},{letter:"B",text:"An approach combining biological, cultural, physical and chemical tools to minimise economic, health and environmental risks from pests"},{letter:"C",text:"Importing natural predators from other continents to control pests"},{letter:"D",text:"Genetically modifying all crops to be pest-resistant"}],answer:"B",feedback:"IPM prioritises ecological methods (natural predators, crop rotation, resistant varieties) over chemical pesticides, only using pesticides as a last resort — reducing costs, health risks and environmental impact."},
  {id:"week6_gen_16",text:"'Nitrogen fixing' cover crops or legumes benefit agricultural systems by:",options:[{letter:"A",text:"Removing nitrogen from the soil, reducing the need for crop rotation"},{letter:"B",text:"Converting atmospheric nitrogen into plant-available form through symbiotic bacteria, reducing the need for synthetic nitrogen fertilisers"},{letter:"C",text:"Absorbing excess water from the soil to prevent flooding"},{letter:"D",text:"Producing natural herbicides that eliminate weeds"}],answer:"B",feedback:"Legumes (beans, peas, clover) host rhizobial bacteria in root nodules that fix atmospheric N₂ into ammonia; this reduces reliance on energy-intensive synthetic nitrogen fertilisers, cutting costs and emissions."},
  {id:"week6_gen_17",text:"SDG 2 target 2.4 calls for ensuring sustainable food production systems and resilient agricultural practices by 2030. Which of the following is explicitly mentioned in this target?",options:[{letter:"A",text:"Doubling the land area under organic certification"},{letter:"B",text:"Practices that increase productivity and production, maintain ecosystems, strengthen capacity for climate adaptation and progressively improve land and soil quality"},{letter:"C",text:"Eliminating all forms of animal agriculture"},{letter:"D",text:"Requiring all countries to achieve food self-sufficiency"}],answer:"B",feedback:"SDG 2.4 specifies sustainable agricultural practices that are productive, maintain ecosystems, are resilient, support ecosystem services and adapt to climate change and extreme weather — not prescribing specific methods like organics."},
  {id:"week6_gen_18",text:"The 'food environment' refers to:",options:[{letter:"A",text:"The physical climate conditions where food is grown"},{letter:"B",text:"The physical, economic, political and socio-cultural context in which consumers engage with the food system to make decisions about food acquisition and consumption"},{letter:"C",text:"The government regulations governing food labelling only"},{letter:"D",text:"The natural ecosystems within which agriculture occurs"}],answer:"B",feedback:"The food environment shapes what people eat — it includes the availability, affordability, convenience and desirability of foods, shaped by retail, marketing, pricing, urban design and cultural norms."},
  {id:"week6_gen_19",text:"Reducing food waste at the consumer level in high-income countries is most effectively achieved through:",options:[{letter:"A",text:"Increasing food prices to discourage consumption"},{letter:"B",text:"Better consumer education on meal planning, portion sizes, storage and date labelling, combined with packaging redesign and food recovery schemes"},{letter:"C",text:"Restricting supermarkets from selling perishable items"},{letter:"D",text:"Mandatory fasting programmes for all citizens"}],answer:"B",feedback:"Consumer food waste reduction requires multiple approaches: education, clearer date labelling (best-before vs use-by), appropriate packaging sizes, food recovery apps and cultural shifts around wasting food."},
  {id:"week6_gen_20",text:"Which UN agency has primary responsibility for food and agriculture at the global level?",options:[{letter:"A",text:"UNICEF"},{letter:"B",text:"FAO (Food and Agriculture Organization)"},{letter:"C",text:"WHO"},{letter:"D",text:"UNDP"}],answer:"B",feedback:"The FAO is the UN agency leading international efforts on food security, nutrition, sustainable agriculture, fisheries and forestry; it produces the annual State of Food Security and Nutrition in the World report."},
  {id:"week6_gen_21",text:"Agroforestry is a sustainable land-use practice that involves:",options:[{letter:"A",text:"Clearing forests to create large monoculture fields"},{letter:"B",text:"Deliberately integrating trees and shrubs into crop and livestock farming systems to achieve ecological and economic benefits"},{letter:"C",text:"Growing only tree crops such as coffee and cocoa"},{letter:"D",text:"Converting agricultural land into forests for carbon credits only"}],answer:"B",feedback:"Agroforestry combines woody perennials with crops and/or livestock; trees provide shade, fix nitrogen, reduce erosion, sequester carbon, provide fruit and timber, and increase overall farm resilience and biodiversity."},
  {id:"week6_gen_22",text:"The FAO defines food system 'sustainability' as requiring that the system:",options:[{letter:"A",text:"Produces the maximum possible calories regardless of resource use"},{letter:"B",text:"Delivers food security and nutrition for all without compromising the economic, social and environmental bases to deliver food security and nutrition for future generations"},{letter:"C",text:"Is free from any government intervention"},{letter:"D",text:"Relies exclusively on local food production with no trade"}],answer:"B",feedback:"FAO's definition of a sustainable food system balances present food security needs with the integrity of ecosystems and social equity across generations — preventing resource depletion that would undermine future food systems."},
  {id:"week6_gen_23",text:"'Soil degradation' is a critical threat to food security because:",options:[{letter:"A",text:"Degraded soil produces crops with higher yields in the short term"},{letter:"B",text:"Approximately 33% of global soils are already moderately to highly degraded, reducing their ability to support crop production and threatening long-term food security"},{letter:"C",text:"Soil degradation only affects dryland farming systems"},{letter:"D",text:"The food system does not depend on soil health because hydroponics can replace soil-based agriculture"}],answer:"B",feedback:"FAO estimates one-third of global soils are degraded from erosion, salinisation, compaction, pollution and organic matter loss — posing a direct threat to agricultural productivity and long-term food security."},
  {id:"week6_gen_24",text:"SDG 2 target 2.3 aims to double the agricultural productivity and incomes of small-scale food producers by 2030. Achieving this requires:",options:[{letter:"A",text:"Replacing smallholder farming with large-scale industrial agriculture"},{letter:"B",text:"Secure and equal access to land, other productive resources, inputs, knowledge and markets for small-scale producers including women, indigenous peoples and family farmers"},{letter:"C",text:"Eliminating all agricultural subsidies globally"},{letter:"D",text:"Restricting smallholders from selling in international markets"}],answer:"B",feedback:"SDG 2.3 explicitly targets doubling smallholder productivity through equitable access to land, productive resources, financial services, markets and value-addition opportunities — especially for women and marginalised groups."},
  {id:"week6_gen_25",text:"The concept of 'food miles' refers to:",options:[{letter:"A",text:"The total distance food travels from production to consumption — used as an indicator of the environmental footprint of food transport"},{letter:"B",text:"A loyalty scheme offered by supermarkets to reward customers"},{letter:"C",text:"The length of a food supply chain measured in number of intermediaries"},{letter:"D",text:"The area of land required to produce a specific food item"}],answer:"A",feedback:"Food miles measure transport distance as a proxy for the carbon footprint of food; however, studies show transport is often a small fraction of total food system emissions — production method and food type are often more significant."},
  {id:"week6_gen_26",text:"Genetically modified organisms (GMOs) in agriculture are most contentious because of debates about:",options:[{letter:"A",text:"Their colour and appearance in stores"},{letter:"B",text:"Potential ecological effects (gene flow to wild species), corporate control of seeds, food safety concerns, loss of farmer seed sovereignty and regulatory inconsistencies between countries"},{letter:"C",text:"The impossibility of growing them in tropical climates"},{letter:"D",text:"Their exclusive association with drought resistance"}],answer:"B",feedback:"GMO debates involve ecological risks (herbicide-resistant weeds, biodiversity loss), corporate seed monopolisation (IP rights), consumer safety concerns and farmer autonomy — reflecting tensions between technological optimism and precaution."},
  {id:"week6_gen_27",text:"'Climate-smart agriculture' (CSA) practices for adaptation to climate variability include:",options:[{letter:"A",text:"Increasing reliance on a single high-yielding variety to maximise output"},{letter:"B",text:"Crop diversification, drought-tolerant varieties, water harvesting, conservation agriculture and improved agro-meteorological information services"},{letter:"C",text:"Concentrating all production in currently productive regions and abandoning marginal areas"},{letter:"D",text:"Removing trees from farmland to reduce competition for water"}],answer:"B",feedback:"CSA adaptation strategies build resilience through diverse crops, improved varieties suited to changing conditions, better water management, soil conservation and timely climate information for decision-making."},
  {id:"week6_gen_28",text:"Which of the following best describes 'sustainable intensification' of agriculture?",options:[{letter:"A",text:"Increasing food production area by clearing more forests"},{letter:"B",text:"Producing more food from the same or less area of land while reducing negative environmental impacts"},{letter:"C",text:"Using maximum synthetic inputs to achieve the highest possible yield"},{letter:"D",text:"Reducing food production to protect biodiversity"}],answer:"B",feedback:"Sustainable intensification aims to increase yields on existing agricultural land without expanding the farm frontier into natural ecosystems, while simultaneously reducing the environmental footprint per unit of food produced."},
  {id:"week6_gen_29",text:"The 'tragedy of the commons' applied to fisheries and grazing lands illustrates the risk that:",options:[{letter:"A",text:"Common resources are always well managed because no one owns them"},{letter:"B",text:"Without governance or collective management, shared resources will be over-exploited by individual actors pursuing self-interest, leading to resource depletion"},{letter:"C",text:"Government ownership always prevents over-exploitation"},{letter:"D",text:"Only private ownership prevents resource degradation"}],answer:"B",feedback:"Hardin's 'tragedy of the commons' warns that shared resources (oceans, grazing lands) face over-exploitation absent rules; sustainable management requires community governance, clear rights or regulation — as Elinor Ostrom's work showed is achievable."},
  {id:"week6_gen_30",text:"The Voluntary Guidelines on the Responsible Governance of Tenure of Land, Fisheries and Forests (VGGT), endorsed by the Committee on World Food Security in 2012, primarily aim to:",options:[{letter:"A",text:"Promote large-scale land acquisition by multinational corporations"},{letter:"B",text:"Improve tenure governance to protect the rights of all legitimate tenure rights holders, especially the poor and vulnerable, and to promote food security"},{letter:"C",text:"Privatise all communal and customary land globally"},{letter:"D",text:"Establish a global land registration database"}],answer:"B",feedback:"The VGGT provide guidance for improving governance of tenure of land, fisheries and forests, with specific attention to protecting vulnerable groups' existing rights and preventing land grabs that threaten food security."},
  {id:"week6_gen_31",text:"Rainwater harvesting in agriculture contributes to water security by:",options:[{letter:"A",text:"Increasing dependence on groundwater extraction"},{letter:"B",text:"Collecting and storing rainfall for productive use, reducing reliance on erratic rainfall patterns and recharging local aquifers"},{letter:"C",text:"Diverting river water for irrigation purposes"},{letter:"D",text:"Replacing irrigation needs entirely in all climate zones"}],answer:"B",feedback:"Rainwater harvesting — through ponds, terraces, sand dams and micro-catchments — captures rainfall for dry-season use, improving water availability for smallholders in rainfed agricultural systems."},
  {id:"week6_gen_32",text:"The 'farm-to-fork' strategy of the European Union aims to:",options:[{letter:"A",text:"Maximise agricultural exports from EU member states"},{letter:"B",text:"Make food systems fair, healthy and environmentally friendly by addressing the entire food chain from production to consumption"},{letter:"C",text:"Eliminate all pesticide use from EU agriculture immediately"},{letter:"D",text:"Promote only organic farming in EU member states"}],answer:"B",feedback:"The EU Farm to Fork Strategy (2020), part of the European Green Deal, sets targets for reducing pesticide use, increasing organic farming, cutting fertiliser use and improving animal welfare across the EU food system."},
  {id:"week6_gen_33",text:"Pollinators (bees, butterflies, etc.) are critical to food security because:",options:[{letter:"A",text:"They make food more colourful and attractive to consumers"},{letter:"B",text:"About 75% of leading global food crops depend to some extent on animal pollination; pollinator decline threatens crop yields and global food supply"},{letter:"C",text:"They are only important for honey production, not staple crops"},{letter:"D",text:"They replace the need for chemical fertilisers"}],answer:"B",feedback:"Animal pollinators are essential for the production of fruits, vegetables, nuts and seeds; their global decline — from pesticides, habitat loss and disease — is a direct threat to food diversity, nutrition and agricultural livelihoods."},
  {id:"week6_gen_34",text:"The concept of 'agroecological transition' implies that moving toward sustainable food systems:",options:[{letter:"A",text:"Can be achieved overnight through government decrees"},{letter:"B",text:"Is a multi-level process involving gradual changes in practices, knowledge systems, governance and market structures, typically taking years to decades"},{letter:"C",text:"Only involves individual farmers changing their production methods"},{letter:"D",text:"Requires abandoning all modern agricultural technology"}],answer:"B",feedback:"Agroecological transition is a systemic, multi-actor process — requiring changes in farmer knowledge and practice, food system governance, market incentives, research priorities and policy support — not a simple on/off switch."},
  {id:"week6_gen_35",text:"Which of the following is a major greenhouse gas (GHG) emitted by the agriculture sector?",options:[{letter:"A",text:"Nitrogen dioxide (NO₂)"},{letter:"B",text:"Methane (CH₄) from livestock enteric fermentation and rice paddies, and nitrous oxide (N₂O) from fertiliser application"},{letter:"C",text:"Carbon monoxide (CO) from fuel combustion in tractors only"},{letter:"D",text:"Ozone (O₃) from crop fields"}],answer:"B",feedback:"Agriculture produces significant methane (from cattle and wetland rice) and nitrous oxide (from synthetic and organic fertilisers); together these are potent GHGs, making the sector responsible for roughly 10-12% of global GHG emissions."},
  {id:"week6_gen_36",text:"The 'paradox of food systems' in the context of SDG 2 refers to the situation where:",options:[{letter:"A",text:"More food is produced than the world needs, yet 820+ million people remain hungry"},{letter:"B",text:"Only developing countries face food insecurity"},{letter:"C",text:"Agricultural yields have stopped growing globally"},{letter:"D",text:"Food surpluses automatically solve undernutrition problems"}],answer:"A",feedback:"The food systems paradox highlights that global food production exceeds caloric need yet hunger persists alongside obesity and malnutrition — due to inequitable distribution, poverty, food loss/waste and access barriers."},
  {id:"week6_gen_37",text:"Participatory plant breeding (PPB) differs from conventional plant breeding because it:",options:[{letter:"A",text:"Is conducted exclusively by private seed companies in controlled laboratories"},{letter:"B",text:"Involves farmers — especially women — in the selection and development of crop varieties, ensuring varieties suit local conditions and farmer priorities"},{letter:"C",text:"Produces patented varieties that farmers must purchase annually"},{letter:"D",text:"Only uses wild plant relatives, not cultivated varieties"}],answer:"B",feedback:"Participatory plant breeding engages farming communities as co-creators of new varieties; it produces locally adapted seeds that farmers can save and share, maintaining seed sovereignty and agrobiodiversity."},
  {id:"week6_gen_38",text:"The 'right to food' under international law means:",options:[{letter:"A",text:"Every government must provide free food to all citizens at all times"},{letter:"B",text:"Every person has the right to regular, permanent and unrestricted access to quantitatively and qualitatively adequate and sufficient food corresponding to cultural traditions and ensuring a fulfilling life free from fear"},{letter:"C",text:"Countries may only import food from nations that respect human rights"},{letter:"D",text:"The right to food applies only to children and pregnant women"}],answer:"B",feedback:"The right to food (General Comment 12 of the UN Committee on Economic, Social and Cultural Rights) obliges states to respect, protect and fulfil access to adequate, nutritious, culturally appropriate food for all people."},
  {id:"week6_gen_39",text:"Which of the following best illustrates 'value chain upgrading' for smallholder farmers?",options:[{letter:"A",text:"Farmers selling raw produce at farm gate prices to middlemen"},{letter:"B",text:"Farmers gaining access to processing, grading, packaging and direct market linkages so they capture a higher share of consumer food prices"},{letter:"C",text:"Governments purchasing all produce at fixed prices"},{letter:"D",text:"Large corporations buying farms directly to control production"}],answer:"B",feedback:"Value chain upgrading enables smallholders to move from selling low-value raw commodities to capturing value through processing, quality differentiation and direct market access — increasing incomes and reducing poverty."},
  {id:"week6_gen_40",text:"'Biofortification' as a strategy to address micronutrient deficiency involves:",options:[{letter:"A",text:"Adding synthetic vitamins to processed foods during manufacturing"},{letter:"B",text:"Breeding or developing crop varieties that have higher concentrations of key micronutrients (e.g., iron-rich beans, vitamin A-rich orange sweet potato)"},{letter:"C",text:"Providing vitamin tablets to all school children"},{letter:"D",text:"Replacing staple crops with imported nutritionally superior foods"}],answer:"B",feedback:"Biofortification uses conventional breeding or biotechnology to increase micronutrient content in staple crops; once distributed to farmers, the nutritional benefit reaches consumers without depending on ongoing supplementation programmes."},
  {id:"week6_gen_41",text:"The Committee on World Food Security (CFS) is significant in global food governance because:",options:[{letter:"A",text:"It sets binding international food safety standards"},{letter:"B",text:"It is the foremost inclusive international and intergovernmental platform for all stakeholders to work together to ensure food security and nutrition for all"},{letter:"C",text:"It controls all FAO funding and research"},{letter:"D",text:"It is a private sector body representing global agribusiness"}],answer:"B",feedback:"Reformed in 2009, the CFS is unique as an inclusive multi-stakeholder platform within the UN system where governments, civil society, the private sector and research institutions jointly develop food security and nutrition policies."},
  {id:"week6_gen_42",text:"Land degradation neutrality (LDN), a target under SDG 15 closely linked to food security, means:",options:[{letter:"A",text:"Keeping all land permanently free of human use"},{letter:"B",text:"A state whereby the amount and quality of land resources necessary to support ecosystem functions and services remains stable or increases within specified temporal and spatial scales"},{letter:"C",text:"Reducing all land under cultivation by 50%"},{letter:"D",text:"Eliminating all forms of agriculture to restore natural land cover"}],answer:"B",feedback:"LDN aims to ensure that land degraded by agriculture, infrastructure and other uses is counterbalanced by restoration of degraded lands, maintaining the overall stock of healthy land for food production and ecosystem services."},
  {id:"week6_gen_43",text:"Which farming practice is associated with reducing carbon in the soil and improving climate resilience?",options:[{letter:"A",text:"Deep ploughing after every harvest to expose soil to sun"},{letter:"B",text:"Soil carbon sequestration through compost addition, cover cropping and reduced tillage, building organic matter and improving soil structure"},{letter:"C",text:"Repeated burning of crop residues to clear fields quickly"},{letter:"D",text:"Heavy use of ammonium nitrate fertiliser"}],answer:"B",feedback:"Building soil organic matter through compost, cover crops and minimum tillage sequesters carbon in the soil, improving fertility, water retention and resilience to drought — a key CSA mitigation and adaptation co-benefit."},
  {id:"week6_gen_44",text:"The 'inverse relationship' between farm size and productivity observed in many studies suggests that:",options:[{letter:"A",text:"Larger farms are always more productive per unit area"},{letter:"B",text:"Smaller farms often achieve higher output per hectare through more intensive use of family labour, knowledge and diversified management"},{letter:"C",text:"Farm size has no relationship to agricultural productivity"},{letter:"D",text:"Only irrigated farms show this pattern"}],answer:"B",feedback:"The inverse farm size-productivity relationship is a well-documented empirical finding: smallholders' intensive management, multiple cropping and attentiveness often produces higher yields per unit area than large-scale extensive farming."},
  {id:"week6_gen_45",text:"The 'post-harvest loss' problem in developing countries contributes to food insecurity by:",options:[{letter:"A",text:"Increasing food availability in urban markets"},{letter:"B",text:"Reducing the quantity and quality of food available to consumers and income earned by farmers through inadequate storage, handling and processing infrastructure"},{letter:"C",text:"Creating surpluses that depress food prices benefiting consumers"},{letter:"D",text:"Only affecting export crop value chains, not food crops"}],answer:"B",feedback:"Post-harvest losses (estimated at 15-50% of production depending on crop and region) waste farmers' labour and inputs, reduce food available for consumption, lower farmer incomes and contribute to food price volatility."},
  {id:"week6_gen_46",text:"The Svalbard Global Seed Vault serves food security by:",options:[{letter:"A",text:"Producing high-yielding commercial seeds for global distribution"},{letter:"B",text:"Providing a secure back-up storage facility for duplicates of the world's crop diversity held in gene banks, protecting against natural and human-made disasters"},{letter:"C",text:"Testing genetically modified organisms under controlled Arctic conditions"},{letter:"D",text:"Storing emergency food reserves for use in global famines"}],answer:"B",feedback:"The Svalbard vault, carved into a Norwegian Arctic mountainside, stores over 1.3 million seed samples as an insurance policy against gene bank failures and catastrophic loss of agricultural biodiversity."},
  {id:"week6_gen_47",text:"SDG 2 target 2.5 specifically calls for the maintenance of genetic diversity of seeds, cultivated plants and farmed and domesticated animals by 2020. This target is important because:",options:[{letter:"A",text:"Genetic diversity has no practical importance for modern agriculture"},{letter:"B",text:"Genetic diversity in crops and livestock provides the raw material for breeding varieties adapted to new pests, diseases and climatic conditions — it is the foundation of long-term food security"},{letter:"C",text:"Maintaining diversity means all farmers must grow heritage varieties"},{letter:"D",text:"Genetic diversity only matters for pharmaceutical research"}],answer:"B",feedback:"Crop and livestock genetic diversity is essential insurance for the future: breeders need diverse genetic material to develop varieties that can withstand emerging threats from climate change, new pests and evolving pathogens."},
  {id:"week6_gen_48",text:"Which of the following is a co-benefit of reducing food waste that links food systems to climate goals?",options:[{letter:"A",text:"Higher food prices benefiting farmers"},{letter:"B",text:"Reduction in greenhouse gas emissions from food production, transport and decomposition in landfills, as well as reduced pressure on land and water resources"},{letter:"C",text:"Increased need for food storage infrastructure"},{letter:"D",text:"Greater dependence on food imports"}],answer:"B",feedback:"Cutting food loss and waste reduces the GHG emissions embedded in wasted food (production, processing, transport, landfill methane), eases pressure on land, water and biodiversity, and improves economic efficiency across the food system."},
  {id:"week6_gen_49",text:"The term 'agroecological intensification' implies that agricultural productivity is increased through:",options:[{letter:"A",text:"Increasing synthetic chemical inputs and mechanisation"},{letter:"B",text:"Enhancing ecological processes — nutrient cycling, biological control, microclimate regulation — to improve yields while reducing external input dependency"},{letter:"C",text:"Expanding the agricultural land frontier into forests"},{letter:"D",text:"Adopting genetic modification exclusively"}],answer:"B",feedback:"Agroecological intensification harnesses natural ecological functions (symbiotic soil organisms, predator-prey pest control, improved water cycles) to boost productivity sustainably without relying on greater synthetic input use."}
];

existing.week4 = week4;
